steps.action:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{"query":"{ __type(name: \"Query\") { fields { name args { name type { name kind ofType { name } } } } } }"}' | python3 -c "
import json, sys
data = json.load(sys.stdin)
for field in data['data']['__type']['fields']:
    if field['name'] in ['documents', 'document', 'searchDocuments']:
        print(f\"Field: {field['name']}\")
        for arg in field['args']:
            print(f\"  Arg: {arg['name']}\")
        print()
"
